public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long count = 0;
        for (int k = 1; k <= 60; k++) {
            long base = (1L << k) - 1;
            long step = 1L << k;
            long start = base;
            if (start > b) continue;
            long end = start + step - 1;
            long lower = Math.max(a, start);
            long upper = Math.min(b, end);
            if (lower <= upper) {
                count += (upper - lower + 1);
            }
        }
