            long lower = 1L << k;
            long upper = (1L << (k + 1)) - 1;
            if (lower > b) break;
            if (upper < a) continue;
            long cl = Math.max(a, lower);
            long cr = Math.min(b, upper);
            if (cl > cr) continue;
            long cnt = (cr - m) - (cl - 1 - m);
            count += cnt;
        }
        System.out.println(count);
