import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        System.out.println(count(b) - count(a - 1));
    }

    private static long count(long n) {
        if (n < 2) return 0;
        long res = 0;
        for (int m = 1; ; m++) {
            long pow = 1L << m;
            if (pow > n) break;
            long upper = (pow << 1) - 1;
            long max = Math.min(upper, n);
            long cnt = max - pow + 1;
            res += cnt * m;
        }
        return res;
    }
}
